#!/bin/bash
# golang generic package


if [ ! -d /mnt/server/ ]; then
    mkdir -p /mnt/server/
fi

go get ${GO_PACKAGE}

cd src/${GO_PACKAGE}

go get

go build

cp -f ${EXECUTABLE} /mnt/server/

